  ('7058b304-4d63-40d4-a73e-167dee50da2b', '785e49df-e06f-4ecb-a5fe-9f2d996ff41c', null, 'topic'::public.curated_course_node_type, 'International Finance, Hedging, and Enterprise Risk Management', 'Global firms face currency, rate, commodity, country, liquidity, and counterparty risks that interact with operating decisions. Students learn to measure exposures, choose hedges, and distinguish risk reduction from speculative positioning.', 13),
  ('6fc77e28-5a16-427e-9380-1ca04c1a9da8', '785e49df-e06f-4ecb-a5fe-9f2d996ff41c', '7058b304-4d63-40d4-a73e-167dee50da2b', 'subtopic'::public.curated_course_node_type, 'Foreign-exchange and international valuation', 'Keep currency, inflation, growth, tax, and discount-rate assumptions internally consistent.', 0),
  ('c232ef0b-d740-4e47-85e5-084c975db243', '785e49df-e06f-4ecb-a5fe-9f2d996ff41c', '6fc77e28-5a16-427e-9380-1ca04c1a9da8', 'concept'::public.curated_course_node_type, 'Spot, forward, and cross rates', null, 0),
