  ('caa4e7ba-61d9-4e8b-975f-6b94c17e4e21', '785e49df-e06f-4ecb-a5fe-9f2d996ff41c', '6fc77e28-5a16-427e-9380-1ca04c1a9da8', 'concept'::public.curated_course_node_type, 'Local-currency versus home-currency valuation', null, 3),
  ('f3a00fe3-b6c6-4069-9066-ac7eb24311d4', '785e49df-e06f-4ecb-a5fe-9f2d996ff41c', '7058b304-4d63-40d4-a73e-167dee50da2b', 'subtopic'::public.curated_course_node_type, 'Hedging instruments and policy', 'Match exposures to derivatives and controls without assuming every risk should be eliminated.', 1),
