  ('465a6ff3-f5bb-424d-8fa7-da33485fbc9b', '785e49df-e06f-4ecb-a5fe-9f2d996ff41c', '7058b304-4d63-40d4-a73e-167dee50da2b', 'subtopic'::public.curated_course_node_type, 'Enterprise risk management', 'Create a portfolio view of risks, controls, ownership, appetite, and escalation.', 2),
  ('364de041-36d8-4791-befa-211206bbcc3f', '785e49df-e06f-4ecb-a5fe-9f2d996ff41c', '465a6ff3-f5bb-424d-8fa7-da33485fbc9b', 'concept'::public.curated_course_node_type, 'Risk taxonomy, register, and ownership', null, 0),
