  ('0a7baa8a-1f97-4ebb-9f27-d088677c7d6e', '785e49df-e06f-4ecb-a5fe-9f2d996ff41c', null, 'topic'::public.curated_course_node_type, 'Sustainable Finance, Behavioral Decision Quality, and Integrated Capstone', 'The course concludes by testing whether students can integrate value, risk, incentives, uncertainty, and implementation into a recommendation. Sustainability and behavioral finance are treated as decision-quality disciplines, not slogans or detached electives.', 14),
  ('9c12f7dd-8dcb-4a5c-90c8-08b288b16e7a', '785e49df-e06f-4ecb-a5fe-9f2d996ff41c', '0a7baa8a-1f97-4ebb-9f27-d088677c7d6e', 'subtopic'::public.curated_course_node_type, 'Sustainability in capital allocation', 'Translate material environmental and social factors into cash flow, risk, option value, and financing consequences.', 0),
  ('9ff8ca30-c5c6-431b-96cb-76b85865060d', '785e49df-e06f-4ecb-a5fe-9f2d996ff41c', '9c12f7dd-8dcb-4a5c-90c8-08b288b16e7a', 'concept'::public.curated_course_node_type, 'Physical and transition climate risk', null, 0),
