  ('1ec96a75-ba8b-4230-93cf-0a5d58b8209c', '785e49df-e06f-4ecb-a5fe-9f2d996ff41c', '9c12f7dd-8dcb-4a5c-90c8-08b288b16e7a', 'concept'::public.curated_course_node_type, 'Materiality, externalities, stranded assets, and adaptation', null, 2),
  ('83339d92-fff0-4bc8-879a-39be2a69e386', '785e49df-e06f-4ecb-a5fe-9f2d996ff41c', '9c12f7dd-8dcb-4a5c-90c8-08b288b16e7a', 'concept'::public.curated_course_node_type, 'Green financing, transition finance, and credibility risk', null, 3),
  ('a2397355-3c17-41e9-be48-630ca6a8e65b', '785e49df-e06f-4ecb-a5fe-9f2d996ff41c', '0a7baa8a-1f97-4ebb-9f27-d088677c7d6e', 'subtopic'::public.curated_course_node_type, 'Behavioral corporate finance', 'Recognize predictable biases that can distort forecasts, investments, financing, and transactions.', 1),
