  ('8b2da037-51d2-491b-bc41-9c082c3be475', '785e49df-e06f-4ecb-a5fe-9f2d996ff41c', 'a2397355-3c17-41e9-be48-630ca6a8e65b', 'concept'::public.curated_course_node_type, 'Pre-mortems, red teams, decision logs, and challenge process', null, 3),
