insert into public.curated_course_resources (course_id, kind, title, link_or_site, description, sort_order)
values
  ('785e49df-e06f-4ecb-a5fe-9f2d996ff41c', 'textbook'::public.curated_course_resource_kind, 'Principles of Finance', 'https://openstax.org/details/books/principles-finance', 'OpenStax. Free foundation for TVM, valuation, risk, capital budgeting, cost of capital, financing, and working capital.', 0),
  ('785e49df-e06f-4ecb-a5fe-9f2d996ff41c', 'textbook'::public.curated_course_resource_kind, 'Principles of Corporate Finance', 'McGraw Hill', 'Brealey, Myers, Allen, and Edmans. Rigorous common reference for investment, financing, payout, risk, options, and international finance.', 1),
  ('785e49df-e06f-4ecb-a5fe-9f2d996ff41c', 'textbook'::public.curated_course_resource_kind, 'Corporate Finance', 'Pearson', 'Berk and DeMarzo. Modern unified treatment with strong valuation logic, applications, and graduate-ready extensions.', 2),
  ('785e49df-e06f-4ecb-a5fe-9f2d996ff41c', 'textbook'::public.curated_course_resource_kind, 'Applied Corporate Finance', 'Wiley', 'Aswath Damodaran. Real-company application of objective, investment, financing, payout, and valuation decisions.', 3),
  ('785e49df-e06f-4ecb-a5fe-9f2d996ff41c', 'textbook'::public.curated_course_resource_kind, 'Valuation: Measuring and Managing the Value of Companies', 'Wiley', 'Koller, Goedhart, and Wessels. Enterprise DCF, value drivers, ROIC, growth, multiples, and managerial value creation.', 4),
  ('785e49df-e06f-4ecb-a5fe-9f2d996ff41c', 'textbook'::public.curated_course_resource_kind, 'Financial Modeling', 'MIT Press', 'Simon Benninga. Spreadsheet-based finance models, valuation, simulation, options, and implementation practice.', 5),
  ('785e49df-e06f-4ecb-a5fe-9f2d996ff41c', 'textbook'::public.curated_course_resource_kind, 'Investment Banking: Valuation, LBOs, M' || chr(38) || 'A, and IPOs', 'Wiley', 'Rosenbaum and Pearl. Practitioner reference for comps, precedents, DCF, sources and uses, M' || chr(38) || 'A, and LBO models.', 6),
  ('785e49df-e06f-4ecb-a5fe-9f2d996ff41c', 'textbook'::public.curated_course_resource_kind, 'The Theory of Corporate Finance', 'Princeton University Press', 'Jean Tirole. MS Finance extension for contracting, governance, incentives, capital structure, and control.', 7),
  ('785e49df-e06f-4ecb-a5fe-9f2d996ff41c', 'website'::public.curated_course_resource_kind, 'MIT Sloan 15.401 Finance Theory I', 'https://ocw.mit.edu/courses/15-401-finance-theory-i-fall-2008/', 'Graduate lectures, notes, problems, and exams on valuation, risk, asset pricing, options, capital budgeting, and markets.', 8),
  ('785e49df-e06f-4ecb-a5fe-9f2d996ff41c', 'website'::public.curated_course_resource_kind, 'Wharton FNCE 6110 Corporate Finance', 'https://fnce.wharton.upenn.edu/programs/mba/course-descriptions/', 'Benchmark description for rigorous DCF, uncertainty, asset pricing, options, market efficiency, and financial policy.', 9),
  ('785e49df-e06f-4ecb-a5fe-9f2d996ff41c', 'website'::public.curated_course_resource_kind, 'NYU Stern Damodaran Corporate Finance', 'https://pages.stern.nyu.edu/~adamodar/New_Home_Page/corpfin.html', 'Full course, current lecture packets, spreadsheets, datasets, cases, problems, exams, and real-company projects.', 10),
  ('785e49df-e06f-4ecb-a5fe-9f2d996ff41c', 'website'::public.curated_course_resource_kind, 'SEC EDGAR', 'https://www.sec.gov/edgar/search/', 'Company filings, notes, risk factors, segment data, debt terms, and transaction documents.', 11),
  ('785e49df-e06f-4ecb-a5fe-9f2d996ff41c', 'website'::public.curated_course_resource_kind, 'Federal Reserve Economic Data', 'https://fred.stlouisfed.org/', 'Interest rates, inflation, spreads, macro assumptions, and time-series context.', 12),
  ('785e49df-e06f-4ecb-a5fe-9f2d996ff41c', 'website'::public.curated_course_resource_kind, 'CFA Institute Insights', 'https://www.cfainstitute.org/insights', 'Professional research on valuation, corporate issuers, ethics, risk, sustainability, and markets.', 13);
